SELECT DATE_TRUNC('QUARTER', end_date) AS quarter_start, CASE WHEN monthly_fee >= 235 THEN 'LARGE' ELSE 'SMALL' END AS monthly_fee_tier, STDDEV_SAMP(monthly_fee) AS monthly_fee_stddev, COUNT_IF(plan = 'enterprise') AS enterprise_events, COUNT_IF(status = 'ACTIVE') AS active_events FROM subscriptions GROUP BY DATE_TRUNC('QUARTER', end_date), CASE WHEN monthly_fee >= 235 THEN 'LARGE' ELSE 'SMALL' END HAVING enterprise_events < 1000 ORDER BY quarter_start
